/* 자동 생성 파일: 직접 수정하지 말고 tools/build_popup_bundle.py를 다시 실행하세요. */
window.KEPCO_POPUP_BUNDLE = Object.assign(window.KEPCO_POPUP_BUNDLE || {}, {
"popups/SRMPartnerBidJoin/bidDocCancelConfirmModal.html": "<div class=\"modal-backdrop\" id=\"bidDocCancelConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"bidDocCancelConfirmTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"bidDocCancelConfirmTitle\">입찰 서류 제출 취소 시 유의사항</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">입찰 서류 제출을 취소하면 제출된 서류를 수정할 수 있습니다.</p>\n            <p>단, '입찰 마감 일시' 내에 '입찰 서류 제출'을 완료해야 합니다. 입찰 서류 제출을 취소하시겠습니까?</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><span class=\"description-marker-anchor\"><span class=\"description-target-marker\" aria-hidden=\"true\">2’</span><button type=\"button\" class=\"btn-delete modal-close\">입찰 서류 제출 취소</button></span><button type=\"button\" class=\"btn-secondary modal-close\">취소</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerBidJoin/bidDocSubmitConfirmModal.html": "<div class=\"modal-backdrop\" id=\"bidDocSubmitConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"bidDocSubmitConfirmTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"bidDocSubmitConfirmTitle\">입찰 서류 제출 시 유의사항</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">입찰 서류를 제출합니다. 입찰 서류 제출 후에는 '입찰 참여 현황' 메뉴를 통해 내역을 확인/관리하실 수 있습니다.</p>\n            <p>입찰 서류를 제출하시겠습니까?</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <span class=\"description-marker-anchor\">\n          <span class=\"description-target-marker\" aria-hidden=\"true\">6’</span>\n          <button type=\"button\" class=\"btn-critical-primary\" data-close-modal data-href=\"SRMPartnerBidDocumentComplete.html\">입찰 서류 제출</button>\n        </span>\n        <button type=\"button\" class=\"btn-secondary modal-close\">취소</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerBidJoin/bidDocSubmitDoneModal.html": "<div class=\"modal-backdrop\" id=\"bidDocSubmitDoneModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"bidDocSubmitDoneTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"bidDocSubmitDoneTitle\">입찰 서류 제출 완료</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box success\" role=\"note\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M20 6 9 17l-5-5\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">입찰 서류 제출이 완료되었습니다.</p>\n            <p>만약 '가격 투찰'을 진행하지 않으셨다면, 입찰 마감일 이전에 '가격 투찰'을 반드시 진행하세요. ('가격 투찰'이 누락되면 입찰 참여가 누락됩니다.) '입찰 참여 현황' 메뉴를 통해 진행현황을 확인/관리하실 수 있습니다.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><span class=\"description-marker-anchor\"><span class=\"description-target-marker\" aria-hidden=\"true\">1</span><button type=\"button\" class=\"btn-primary modal-close\">'입찰 참여 현황' 바로가기</button></span></div>\n    </div>\n  </div>",
"popups/SRMPartnerBidJoin/bidGiveUpConfirmModal.html": "<div class=\"modal-backdrop\" id=\"bidGiveUpConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"bidGiveUpConfirmTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"bidGiveUpConfirmTitle\">입찰 포기 시 유의사항</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">입찰을 포기하면 더 이상 본 입찰공고에 입찰 참여를 할 수 없습니다.</p>\n            <p>입찰을 포기하시겠습니까? (포기 시 제출상태가 '입찰 포기'로 변경되며, 고객통보 MSG-014가 발송됩니다.)</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-delete modal-close\">입찰 포기</button><button type=\"button\" class=\"btn-secondary modal-close\">취소</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerBidJoin/bidJoinLimitNoticeModal2.html": "<div class=\"modal-backdrop\" id=\"bidJoinLimitNoticeModal2\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"bidJoinLimitTitle2\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"bidJoinLimitTitle2\">입찰 참여 제한 안내</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning description-marker-container\" role=\"alert\">\n          <span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">2</span>\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\"><p class=\"notice-lead\">본 입찰은 계약방법이 '경쟁입찰(지명)' 건으로 제한(지명)된 업체만 입찰이 가능합니다.</p><p>입찰 참여가 가능한 업체만 참여할 수 있습니다.</p></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-primary\" data-close-modal data-href=\"SRMPartnerBidDocumentSubmit.html\">계속</button><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerBidJoin/bidPriceDrawModal.html": "<div class=\"modal-backdrop\" id=\"bidPriceDrawModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"bidPriceDrawTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"bidPriceDrawTitle\">예비가 추첨하기</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box description-marker-container\" role=\"note\">\n          <span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">1</span>\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 16v-4\"/><path d=\"M12 8h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">본 입찰공고는 가격 투찰 시 '예비가 추첨'이 필요합니다.</p>\n            <p>입찰의 공정성을 부여하기 위해 진행되는 업무입니다. 아래의 15개 예비가 중 하나를 선택해주세요.</p>\n          </div>\n        </div>\n        <div class=\"srm-table-wrap content-inner-gap-top\">\n          <table class=\"data-table\" aria-label=\"예비가 추첨 번호\">\n            <tbody>\n              <tr><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">1</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">2</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">3</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">4</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">5</label></td></tr>\n              <tr><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">6</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">7</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">8</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">9</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">10</label></td></tr>\n              <tr><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">11</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">12</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">13</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">14</label></td><td><label class=\"form-choice\"><input type=\"radio\" name=\"drawNo\">15</label></td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <button type=\"button\" class=\"btn-primary\" data-close-modal data-open-modal=\"bidPriceSubmitConfirmModal\">예비가 추첨하기</button>\n        <button type=\"button\" class=\"btn-secondary modal-close\">취소</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerBidJoin/bidPriceLimitNoticeModal2.html": "<div class=\"modal-backdrop\" id=\"bidPriceLimitNoticeModal2\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"bidPriceLimitTitle2\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\"><h2 class=\"modal-title\" id=\"bidPriceLimitTitle2\">가격 투찰 제한 안내</h2><button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button></div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\"><p class=\"notice-lead description-marker-container\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">3’</span>가격 투찰을 위해서는 반드시 '입찰 서류'가 먼저 제출되어야 합니다.</p><p class=\"description-marker-container\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">3’</span>입찰 서류를 제출하신 후 가격을 투찰해주세요.</p></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerBidJoin/bidPriceSubmitConfirmModal.html": "<div class=\"modal-backdrop\" id=\"bidPriceSubmitConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"bidPriceSubmitConfirmTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"bidPriceSubmitConfirmTitle\">가격 투찰 시 유의사항</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">가격을 투찰하면 더 이상 가격이 수정되지 않습니다. 정확하게 가격이 입력되었는지 다시 한번 확인 부탁드립니다.</p>\n            <p>가격 투찰을 진행하시겠습니까? (투찰 완료 시 제출상태가 '가격 투찰 완료' 또는 '입찰 참여 완료'로 변경되며, 고객통보 MSG-015가 발송됩니다.)</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <span class=\"description-marker-anchor\">\n          <span class=\"description-target-marker\" aria-hidden=\"true\">2</span>\n          <button type=\"button\" class=\"btn-critical-primary modal-close\">가격 투찰하기</button>\n        </span>\n        <button type=\"button\" class=\"btn-secondary modal-close\">취소</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerBidJoin/negoTalkSubmitConfirmModal.html": "<div class=\"modal-backdrop\" id=\"negoTalkSubmitConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"negoTalkSubmitConfirmTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"negoTalkSubmitConfirmTitle\">수의시담을 위한 견적 제출 시 유의사항</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">본 견적을 제출하면 더 이상 수정되지 않습니다. 정확하게 가격이 입력되었는지 다시 한번 확인 부탁드립니다.</p>\n            <p>수의시담을 위한 견적 제출을 진행하시겠습니까? (제출 시 진행상태가 '수의시담(견적제출 완료)'로 변경됩니다.)</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <span class=\"description-marker-anchor\">\n          <span class=\"description-target-marker\" aria-hidden=\"true\">2</span>\n          <button type=\"button\" class=\"btn-critical-primary modal-close\">견적 제출하기</button>\n        </span>\n        <button type=\"button\" class=\"btn-secondary modal-close\">취소</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerBidJoin/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descSearchTitle\">\n          <h3 id=\"descSearchTitle\">검색/조회</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">본 검색/조회 목록에는 해당 협력업체가 입찰 참여한(작성중 건 포함) 건만 제공</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">제출상태 정리 : 노란색 영역 참조\n</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descDetailTitle\">\n          <h3 id=\"descDetailTitle\">상세 · 입찰공고 정보</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">‘낙찰(업체 선정)’ 후 수의시담이 진행되는 경우에만 제공되는 탭 메뉴 </pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descEntryTitle\">\n          <h3 id=\"descEntryTitle\">입찰 서류 제출 · 가격 투찰 진입</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">‘입찰 참여 현황 &gt; 입찰 서류 제출’ 화면으로 이동</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">계약방법이 ‘경쟁입찰(지명)’인 경우 입찰계획 수립 당시 등록된 협력업체만 입찰이 가능함</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">3</span><pre class=\"description-source-text\">가격 투찰을 위해서는 반드시 ‘입찰 서류’가 먼저 제출되어야 함\n\n가격투찰이 동시에 진행되지 않는 경우(낙찰자 선정방법이 ‘제한적 최저가’, ‘2단계 경쟁입찰(규격/가격 분리)’인 경우)에 노출되는 팝업\n\n별도로 설정된 ‘투찰 기간’에만 접근 가능</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descWizardTitle\">\n          <h3 id=\"descWizardTitle\">입찰 서류 제출</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">본 입찰에 참여하는 협력업체의 담당자 선택\n\n선택하면 등록된 정보로 아래의 항목 자동 완성</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">입찰 참여 서류에 등록한 순서대로 나열</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">3</span><pre class=\"description-source-text\">자가 심사 항목이 없는 경우 노출</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">4</span><pre class=\"description-source-text\">자가 심사 순서대로 나열하며, 자가심사가 필요 없는 경우 보여주지 않음</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">5</span><pre class=\"description-source-text\">자가심사 항목이 없는 경우 표시</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">6</span><pre class=\"description-source-text\">입찰 서류 제출 시\n\n고객 통보 : MSG-012\n\n입찰 서류가 제출되면 제출상태는 ‘입찰 서류 제출 완료’ 상태로 변경\n\n단,\n가격 투찰 기간이 서류 제출 이후인 경우(낙찰자 선정방법이 ‘제한적 최저가 입찰’, ‘2단계 경쟁입찰(규격/가격 분리)’)에는 ‘입찰 참여 완료’ 상태로 변경\n</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descDoneTitle\">\n          <h3 id=\"descDoneTitle\">입찰 서류 제출 완료</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">‘입찰 참여 현황’ 목록으로 이동</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descSubmittedTitle\">\n          <h3 id=\"descSubmittedTitle\">입찰 서류 제출 내역(제출된 경우)</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">입찰 서류가 제출된 경우(제출상태가 ‘입찰 서류 제출 완료’) 제공되는 화면\n\n‘입찰 서류 제출’은 ‘가격 투찰’과 다르게 입찰마감일시 전까지는 수정/제출할 수 있음</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">‘입찰 서류 제출’은 ‘가격 투찰’과 다르게 입찰마감일시 전까지는 수정/제출할 수 있음\n\n입찰마감일시까지는 제출을 취소하고 재등록 가능하게 구현\n\n고객 통보 : MSG-013</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">3</span><pre class=\"description-source-text\">입찰 포기 시 안내 후 처리\n\n입찰을 포기하면 제출상태는 ‘입찰 포기’ 상태로 변경되며, 메일/SMS 발송됨\n\n단, 입찰을 포기하게 되면 더 이상 본 입찰공고에 입찰 참여를 할 수 없음\n\n고객 통보 : MSG-014</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descPriceBeforeTitle\">\n          <h3 id=\"descPriceBeforeTitle\">가격 투찰(투찰 전)</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">가격 투찰 기간이 별도로 있는 경우 (낙찰자 선정방법이 ‘제한적 최저가 입찰’, 2단계 경쟁입찰(규격/가격 분리)의 경우) 에는\n본 화면에 접근할 수 없음\n\n가격 투찰 기간에만 접근 가능\n</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">협력업체가 적정선(합리적인 가격)에서 가격 투찰을 할 수 있도록, 제공하는 정보\n예정가/예비가 설정 상태에 따라 정보를 제공함\n- 최저가 : 예정가 제공\n- 제한적 최저가 : 복수예비 기초금액\n- 규격/가격 동시 : 예정가 제공\n- 규격/가격 분리 : 예정가 제공\n- 적격 : 복수예비 기초금액</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">3</span><pre class=\"description-source-text\">예비가(낙찰하한가)가 설정된 경우에는 반드시 예비가 추첨을 진행함\n\n예비가는 낙찰자 선정방법이 ‘제한적 최저가 입찰’, ‘적격심사’에 적용되어 있음\n\n‘예비가 추첨하기’ 팝업 호출\n\n</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descPriceDrawTitle\">\n          <h3 id=\"descPriceDrawTitle\">예비가 추첨 · 가격 투찰 확인</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">예비가(낙찰하한가)가 설정된 경우에는 반드시 예비가 추첨을 진행함\n\n예비가는 낙찰자 선정방법이 ‘제한적 최저가 입찰’, ‘적격심사’에 적용되어 있음\n\n‘예비가 추첨하기’ 팝업 호출\n</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">가격투찰이 완료되면\n\n제출상태는 ‘가격 투찰 완료’로 변경\n\n만약 입찰서류와 가격투찰이 모두 완료된 경우에는 제출상태가 ‘입찰 참여 완료’로 변경\n\n고객 통보 : MSG-015</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descPriceAfterTitle\">\n          <h3 id=\"descPriceAfterTitle\">가격 투찰(투찰 완료)</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">가격 투찰이 완료된 경우 제공되는 화면</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">가격 투찰은 되돌릴 수 없으며, 잘못 등록된 경우 ‘입찰 포기’를 진행할 수밖에 없음\n\n입찰 포기 시 안내 후 처리\n\n입찰을 포기하면 제출상태는 ‘입찰 포기’ 상태로 변경\n\n입찰 포기 시 고객통보 : MSG-014</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descResultTitle\">\n          <h3 id=\"descResultTitle\">입찰 결과</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">입찰결과가 도출되지 않았을 때 제공</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">유찰된 경우 제공 </pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">3</span><pre class=\"description-source-text\">협력업체에게 입찰결과를 어떤 범위까지 제공할 것인지 확인 필요</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descNegoListTitle\">\n          <h3 id=\"descNegoListTitle\">수의시담 · 견적 요청 현황</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">1</span><pre class=\"description-source-text\">낙찰(업체 선정) 후 수의시담을 위한 견적이 요청된 경우에만 제공되는 탭 메뉴 </pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">수의시담을 위한 견적이 다수 회 진행된 경우 차수별로 확인할 수 있음</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">3</span><pre class=\"description-source-text\">‘수의시담을 위한 견적 요청 상세정보’ 화면으로 이동</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">4</span><pre class=\"description-source-text\">제출여부에 따라 ‘견적 제출하기’, ‘견적 제출내역’ 버튼 제공</pre></div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descNegoSubmitTitle\">\n          <h3 id=\"descNegoSubmitTitle\">수의시담 · 견적 제출</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">협력업체(낙찰 업체)가 적정선(합리적인 가격)에서 수의시담을 할 수 있도록, 제공하는 정보\n예정가/예비가 설정 상태에 따라 정보를 제공함\n- 최저가 : 예정가 제공\n- 제한적 최저가 : 복수예비 기초금액\n- 규격/가격 동시 : 예정가 제공\n- 규격/가격 분리 : 예정가 제공\n- 적격 : 복수예비 기초금액</pre></div>\n            <div class=\"description-mapping-item\"><span class=\"description-mapping-number\" aria-hidden=\"true\">2</span><pre class=\"description-source-text\">‘견적 제출하기’ 버튼 클릭 시 진행상태를 ‘수의시담(견적제출 완료)’ 로 변경</pre></div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerBidNotice/bidJoinLimitNoticeModal.html": "<div class=\"modal-backdrop\" id=\"bidJoinLimitNoticeModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"bidJoinLimitTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"bidJoinLimitTitle\">입찰 참여 제한 안내</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning description-marker-container\" role=\"alert\">\n          <span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">9</span>\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">본 입찰은 계약방법이 '경쟁입찰(지명)' 건으로 제한(지명)된 업체만 입찰이 가능합니다.</p>\n            <p>입찰 참여가 가능한 업체만 참여할 수 있습니다.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerBidNotice/bidNoticeDocModal.html": "<div class=\"modal-backdrop\" id=\"bidNoticeDocModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"bidNoticeDocTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"bidNoticeDocTitle\">입찰공고 내역서</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <p class=\"modal-field-label\">입찰진행사 : 켑코이에스(주)</p>\n        <div class=\"srm-table-wrap\">\n          <table class=\"data-table\" aria-label=\"입찰공고 기본\">\n            <tbody>\n              <tr><th class=\"w-120\">공고번호</th><td>BD2026-0025</td><th class=\"w-120\">상태</th><td>입찰공고</td></tr>\n              <tr><th>입찰담당자</th><td>이길수</td><th>개찰담당자</th><td>박승길</td></tr>\n              <tr><th>입찰건명</th><td colspan=\"3\" class=\"text-left\">서초동 1601-9 오피스텔 신축공사 중 기계식주차설비공사</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <p class=\"modal-field-label content-object-gap-top\">입찰 진행방법</p>\n        <div class=\"srm-table-wrap\">\n          <table class=\"data-table\" aria-label=\"입찰 진행방법\">\n            <tbody>\n              <tr><th class=\"w-120\">구분</th><td colspan=\"3\">공사</td></tr>\n              <tr><th>계약방법</th><td>경쟁입찰(일반)</td><th class=\"w-120\">낙찰자 선정방법</th><td>제한적 최저가 입찰</td></tr>\n              <tr><th>수행기간</th><td>2026-08-20 ~ 2027-06-30</td><th>수행기간(일수)</th><td>314일</td></tr>\n              <tr><th>납품장소(현장)</th><td colspan=\"3\">현장 내</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <p class=\"modal-field-label content-object-gap-top\">보증금률</p>\n        <div class=\"srm-table-wrap\">\n          <table class=\"data-table\" aria-label=\"보증금률\">\n            <tbody>\n              <tr><th class=\"w-150\">입찰 보증금률</th><td>5%</td><th class=\"w-150\">계약이행 보증금률</th><td>10%</td></tr>\n              <tr><th>하자이행 보증금률</th><td>3%</td><th>하자이행 기간</th><td>3년</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <p class=\"modal-field-label content-object-gap-top\">입찰 일정계획</p>\n        <div class=\"srm-table-wrap\">\n          <table class=\"data-table\" aria-label=\"입찰 일정계획\">\n            <tbody>\n              <tr><th class=\"w-150\">입찰 시작일시</th><td>2026-08-04 16:00</td><th class=\"w-150\">공급업체 등록마감일</th><td>2026-08-10</td></tr>\n              <tr><th>현장설명회(일시/장소)</th><td colspan=\"3\">-</td></tr>\n              <tr><th>입찰참가 신청마감일시</th><td>2026-08-11 16:00</td><th>입찰 마감일시</th><td class=\"text-danger\">2026-08-18 16:00</td></tr>\n              <tr><th>제안발표(일시/장소)</th><td colspan=\"3\">-</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <p class=\"modal-field-label content-object-gap-top\">입찰업체 전달내역</p>\n        <div class=\"srm-table-wrap\">\n          <table class=\"data-table\" aria-label=\"입찰업체 전달내역\">\n            <tbody>\n              <tr><th class=\"w-180\">업체 자격요건</th><td class=\"text-left\">승강기·삭도공사업 면허 보유업체</td></tr>\n              <tr><th>참여신청 제출서류</th><td class=\"text-left\">1. 입찰참가신청서.hwp</td></tr>\n              <tr><th>입찰 제출서류</th><td class=\"text-left\">2. 입찰보증금지급각서.hwp</td></tr>\n              <tr><th>전달사항(비고)</th><td class=\"text-left\">입찰공고문의 입찰 참가자격, 참가신청 및 낙찰자 결정방법을 숙지하여 주시기 바랍니다.</td></tr>\n              <tr><th>입찰업체 배포서류</th><td class=\"text-left\">00. 입찰공고문_재공고(서초동 1601-9 오피스텔 신축공사 중 기계식주차설비공사).pdf</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <p class=\"modal-field-label content-object-gap-top\">입찰 품목</p>\n        <div class=\"srm-table-wrap\">\n          <table class=\"data-table\" aria-label=\"입찰 품목\">\n            <thead><tr><th>품목명</th><th>규격</th><th>단위</th><th>수량</th><th>비고</th></tr></thead>\n            <tbody><tr><td class=\"text-left\">서초동 1601-9 오피스텔 신축공사 중 기계식주차 설치공사</td><td>-</td><td>식</td><td>1</td><td>-</td></tr></tbody>\n          </table>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerBidNotice/bidPriceLimitNoticeModal.html": "<div class=\"modal-backdrop\" id=\"bidPriceLimitNoticeModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"bidPriceLimitTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"bidPriceLimitTitle\">가격 투찰 제한 안내</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead description-marker-container\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">10’</span>가격 투찰을 위해서는 반드시 '입찰 서류'가 먼저 제출되어야 합니다.</p>\n            <p class=\"description-marker-container\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">10’</span>낙찰자 선정방법이 '제한적 최저가', '2단계 경쟁입찰(규격/가격 분리)', '적격심사'의 경우에는 우선 입찰 서류 제출만으로 입찰 참여가 완료되며, 서류를 통한 '규격(기술) 심사' 후 '가격 투찰'이 진행됩니다. (규격(기술) 심사 후 가격 투찰 시점에 별도 통보 드립니다.) 입찰 서류를 제출하신 후 가격을 투찰해주세요.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerBidNotice/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSearchTitle\">\n          <h3 id=\"descriptionSearchTitle\">검색/조회</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">입찰마감일 기준 기간검색</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">‘계약방법’ 에 따른 ‘낙찰자 선정방법’ 으로 검색</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">본공고인지 유찰 후 재공고인지 여부</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">진행상태 정리(노란색 영역 참고)\n\n협력업체에게는 아래의 단계 외에는 보여주지 않음\n공고대기, 공고게시중, 입찰진행중, 입찰마감, 투찰진행중, 투찰마감, 선정완료, 유찰</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">5</span>\n              <pre class=\"description-source-text\">검색 구분 : 공고번호, 입찰 건명</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">6</span>\n              <pre class=\"description-source-text\">입찰공고 내역서 호출(뒷페이지)</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <pre class=\"description-source-text\">협력업체에게는 해당 상태 값만 제공</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionDetailTitle\">\n          <h3 id=\"descriptionDetailTitle\">상세정보</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">현장설명회가 있는 경우에만 노출</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">낙찰자 선정방법이 ‘제한적 최저가 입찰’, ‘2단계 경쟁입찰(규격/가격 분리)’인 경우 입력되는 정보이며, 해당 경우에만 노출</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">낙찰자 선정방법이 ‘제한적 최저가 입찰’, ‘2단계 경쟁입찰(규격/가격 동시)’, ‘2단계 경쟁입찰(규격/가격 분리)’, ‘적격심사’의 경우에만 등록될 수 있으며, 해당 경우에만 등록된 항목 노출</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">낙찰자 선정방법이 ‘2단계 경쟁입찰(규격/가격 동시)’인 경우에만 등록될 수 있으며, 해당 경우에만 등록된 항목 노출</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">5</span>\n              <pre class=\"description-source-text\">낙찰자 선정방법이 ‘2단계 경쟁입찰(규격/가격 동시)’인 경우에만 등록될 수 있으며, 해당 경우에만 등록된 항목 노출(무조건 제안발표를 하는 것은 아님)</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">6</span>\n              <pre class=\"description-source-text\">자가심사가 있건 없건, 심사/평가 항목을 모두 보여줌</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">7</span>\n              <pre class=\"description-source-text\">낙찰자 선정방법이 ‘제한적 최저가’, ‘2단계 경쟁입찰(규격/가격 동시)’, ‘2단계 경쟁입찰(규격/가격 분리)’, ‘적격심사’의 경우에만 등록될 수 있으며, 해당 경우에만 등록된 항목 노출</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">8</span>\n              <pre class=\"description-source-text\">‘입찰 참여 현황 > 입찰 서류 제출’ 화면으로 이동</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">9</span>\n              <pre class=\"description-source-text\">계약방법이 ‘경쟁입찰(지명)’인 경우 입찰계획 수립 당시 등록된 협력업체만 입찰이 가능함</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">10</span>\n              <pre class=\"description-source-text\">가격 투찰을 위해서는 반드시 ‘입찰 서류’가 먼저 제출되어야 함\n\n가격투찰이 동시에 진행되지 않는 경우(낙찰자 선정방법이 ‘제한적 최저가’, ‘2단계 경쟁입찰(규격/가격 분리)’인 경우)에 노출되는 팝업\n\n별도로 설정된 ‘투찰 기간’에만 접근 가능</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerContract/contractChangeDetailModal.html": "<div class=\"modal-backdrop\" id=\"contractChangeDetailModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"contractChangeDetailTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"contractChangeDetailTitle\">계약 변경 내역 상세보기</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"srm-kv-grid\">\n          <div class=\"srm-kv-row\"><dt>계약변경일</dt><dd>2026.09.01</dd></div>\n          <div class=\"srm-kv-row description-marker-container\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">1</span><dt>변경계약 사유</dt><dd data-ui-value=\"period\" data-ui-source=\"change\">'계약금액' 변경 | '납기일/공사기간' 변경</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=amount\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">2</span><dt>기존 계약금액</dt><dd>99,000,000원 (구천구백만원 / VAT 포함)</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=amount\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">2’</span><dt>변경된 계약금액</dt><dd>92,000,000원 (구천이백만원 / VAT 포함)</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=period\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">3</span><dt>기존 납기일/공사기간</dt><dd>2026.07.20 ~ 2027.07.30</dd></div>\n          <div class=\"srm-kv-row description-marker-container\" data-ui-show=\"change=period\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">3’</span><dt>변경된 납기일/공사기간</dt><dd>2026.07.20 ~ 2027.08.30</dd></div>\n          <div class=\"srm-kv-row\"><dt>변경내용(메모)</dt><dd>품목 1종이 제외되어 계약금액을 수정하여 변경계약 하였습니다.</dd></div>\n          <div class=\"srm-kv-row\"><dt>변경 계약서</dt><dd class=\"content-bullet-item\">이미 등록된 파일명.PDF</dd></div>\n          <div class=\"srm-kv-row\"><dt>변경 시 참고서류</dt><dd class=\"content-bullet-item\">이미 등록된 파일명.PDF</dd></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerContract/contractDocSubmitConfirmModal.html": "<div class=\"modal-backdrop\" id=\"contractDocSubmitConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"contractDocSubmitConfirmTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"contractDocSubmitConfirmTitle\">계약 관련 서류 제출 시 유의사항</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">제출 후 관리자의 검토 후 확정 처리됩니다. 확정 처리 전에는 수정하고 다시 제출할 수 있습니다.</p>\n            <p>계약 관련 서류를 제출하시겠습니까?</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><span class=\"description-marker-anchor\"><span class=\"description-target-marker\" aria-hidden=\"true\">4’</span><button type=\"button\" class=\"btn-critical-primary modal-close\">계약 관련 서류 제출하기</button></span><button type=\"button\" class=\"btn-secondary modal-close\">취소</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerContract/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSearchTitle\">\n          <h3 id=\"descriptionSearchTitle\">검색/조회</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">해당 협력업체가 계약(수의계약, 입찰) 건 검색/조회</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">계약방법/낙찰자 선정방법 별 검색 : 당연히 ‘수의계약’이 포함됨</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">진행상태 정의 : 노란 부분 참조</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">검색 구분 : 계약번호, 계약명</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionChangeTitle\">\n          <h3 id=\"descriptionChangeTitle\">계약 정보 · 계약 변경 내역 상세보기</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">변경 사유에 따라 아래의 입력 항목이 노출됨</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">‘계약금액’ 변경 시 노출</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">‘납기일/공사기간’ 변경 시 노출</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionDocSubmitTitle\">\n          <h3 id=\"descriptionDocSubmitTitle\">계약 관련 서류 제출</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">(제출 후 관리자에 의해 확정되기 전) 해당 공고에 설정된 ‘계약이행 보증금률’, ‘선금이행 보증금률’, ‘하자이행 보증금률’을 보여줌</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">만약 ‘발급 필요 없음’으로 설정된 경우 제출대상이 아니라는 메시지를 제공함</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">제출 후 관리자에 의해 확정된 경우 이와 같이 표시함</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">사업이 진행되는 경과에 따라서 단계적으로 해당되는 보증보험 증권을 제출할 수 있음</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <pre class=\"description-source-text\">진행상태를 ‘계약요청(서류제출 완료)’로 변경 </pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerFileRepo/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSearchTitle\">\n          <h3 id=\"descriptionSearchTitle\">검색/조회</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">제목, 내용, 제목+내용 </pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerInfo/infoUpdateConfirmModal.html": "<div class=\"modal-backdrop\" id=\"infoUpdateConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"infoUpdateConfirmTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"infoUpdateConfirmTitle\">기본 정보 수정 요청 시 유의사항</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">수정 요청 후 승인 기간 동안 본 시스템 접속이 제한됩니다.</p>\n            <p>승인에 걸리는 시간은 약 영업일 기준 3일이며, 문의사항은 02-6959-4561로 연락 부탁드립니다.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><span class=\"description-marker-anchor\"><span class=\"description-target-marker\" aria-hidden=\"true\">3</span><button type=\"button\" class=\"btn-critical-primary modal-close\">기본정보 수정 요청</button></span><button type=\"button\" class=\"btn-secondary modal-close\">취소</button></div>\n    </div>\n  </div>",
"popups/SRMPartnerInfo/partnerContactFormModal.html": "<div class=\"modal-backdrop\" id=\"partnerContactFormModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"partnerContactFormTitle\" aria-hidden=\"true\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"partnerContactFormTitle\">담당자 정보 추가/수정</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"srm-kv-grid\">\n          <div class=\"srm-kv-row description-marker-container\"><span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">5</span><dt>담당자 구분</dt><dd><div class=\"form-choice-group\" role=\"radiogroup\"><label class=\"form-choice\"><input type=\"radio\" id=\"contactKindBasic\" name=\"contactKind\" value=\"basic\">기본 담당자</label><label class=\"form-choice\"><input type=\"radio\" id=\"contactKindAdditional\" name=\"contactKind\" value=\"additional\" checked>추가 담당자</label></div></dd></div>\n          <div class=\"srm-kv-row\"><dt>이름 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control fit-360\" id=\"contactName\" placeholder=\"기 입력된 내용\"></dd></div>\n          <div class=\"srm-kv-row\"><dt>이메일 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control w-140 inline-control\" id=\"contactEmailLocal\" placeholder=\"기 입력된 내용\"> @ <select class=\"filter-select w-150 inline-control\" id=\"contactEmailDomain\"><option value=\"\">이메일 선택</option><option value=\"naver.com\">naver.com</option><option value=\"gmail.com\">gmail.com</option><option value=\"direct\">직접 입력</option></select><input type=\"text\" class=\"form-control w-140 inline-control\" id=\"contactEmailDirect\" placeholder=\"직접 입력\" hidden></dd></div>\n          <div class=\"srm-kv-row\"><dt>핸드폰번호 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><select class=\"filter-select w-80 inline-control\" id=\"contactMobilePrefix\"><option>010</option><option>011</option><option>016</option><option>017</option><option>018</option><option>019</option></select> - <input type=\"text\" class=\"form-control w-80 inline-control\" id=\"contactMobileMiddle\"> - <input type=\"text\" class=\"form-control w-80 inline-control\" id=\"contactMobileLast\"></dd></div>\n          <div class=\"srm-kv-row\"><dt>직책 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control fit-360\" id=\"contactPosition\" placeholder=\"기 입력된 내용\"></dd></div>\n          <div class=\"srm-kv-row\"><dt>담당업무 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control fit-360\" id=\"contactDuty\" placeholder=\"기 입력된 내용\"></dd></div>\n          <div class=\"srm-kv-row\"><dt>전화번호 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><select class=\"filter-select w-80 inline-control\" id=\"contactPhonePrefix\"><option>02</option><option>031</option><option>032</option><option>033</option><option>041</option><option>042</option><option>043</option><option>044</option><option>051</option><option>052</option><option>053</option><option>054</option><option>055</option><option>061</option><option>062</option><option>063</option><option>064</option></select> - <input type=\"text\" class=\"form-control w-80 inline-control\" id=\"contactPhoneMiddle\"> - <input type=\"text\" class=\"form-control w-80 inline-control\" id=\"contactPhoneLast\"></dd></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <button type=\"button\" class=\"btn-primary modal-close\" id=\"contactAddButton\">추가</button>\n        <button type=\"button\" class=\"btn-primary modal-close\" id=\"contactUpdateButton\" hidden>수정</button>\n        <button type=\"button\" class=\"btn-delete modal-close\" id=\"contactDeleteButton\" hidden>삭제</button>\n        <button type=\"button\" class=\"btn-secondary modal-close\">취소</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerInfo/pwChangeDoneModal.html": "<div class=\"modal-backdrop\" id=\"pwChangeDoneModal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pwChangeDoneTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"pwChangeDoneTitle\">비밀번호 변경</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box success\" role=\"note\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M20 6 9 17l-5-5\"/></svg></span>\n          <div class=\"notice-body\"><p class=\"notice-lead\">비밀번호가 변경되었습니다. 다시 로그인해주세요.</p></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><a href=\"../01_협력업체창구_로그인전/SRMLogin.html\" class=\"btn-primary\">로그인 화면으로 이동</a></div>\n    </div>\n  </div>",
"popups/SRMPartnerInfo/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionInfoTitle\">\n          <h3 id=\"descriptionInfoTitle\">협력업체 정보 확인</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">협력업체는 담당자를 여러 명 등록할 수 있음\n\n단, ‘기본 담당자’는 협력업체 신청 시 입력한 담당자임</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionUpdateReqTitle\">\n          <h3 id=\"descriptionUpdateReqTitle\">기본 정보 수정 요청</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">바로 수정되지 않고, 관리자의 내용과 서류검토 후 승인을 통해 수정됨\n\n단, 관리자의 거절 시 이전 승인되었을 때의 상태로 되돌아와야 한다는 것을 염두에 둘 것(개발자 대상 주요 전달사항)\n\n임시테이블에 저장한 후 관리자에 의해 승인되면 반영.\n또한 거절되면 원복(롤백) 해야 함</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">고객 통보 : MSG-007</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionContactTitle\">\n          <h3 id=\"descriptionContactTitle\">담당자 정보 추가/수정</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">협력업체 신청 시 등록한 담당자(기본 담당자)는 삭제할 수 없음(정보 수정은 가능함) </pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">5</span>\n              <pre class=\"description-source-text\">협력업체에 기본 담당자는 한 명만 존재할 수 있음.\n\nAlert ‘기본 담당자가 이미 설정되어 있습니다. 기본 담당자는 반드시 한 명이어야 합니다.’\n\n기본 담당자로 선택한 경우 교체되어야 함</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionPwChangeTitle\">\n          <h3 id=\"descriptionPwChangeTitle\">비밀번호 변경</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">6</span>\n              <pre class=\"description-source-text\">비밀번호 변경 후 Alert 제공 후 다시 로그인 유도할 것\n\nAlert\n“비밀번호가 변경되었습니다. 다시 로그인해주세요.”</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerNegoRequest/negoQuoteSubmitConfirmModal.html": "<div class=\"modal-backdrop\" id=\"negoQuoteSubmitConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"negoQuoteSubmitConfirmTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"negoQuoteSubmitConfirmTitle\">수의계약을 위한 견적 제출 시 유의사항</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">본 견적을 제출하면 더 이상 수정되지 않습니다. 정확하게 가격이 입력되었는지 다시 한번 확인 부탁드립니다.</p>\n            <p>수의계약을 위한 견적 제출을 진행하시겠습니까? (제출 시 진행상태가 '수의계약(견적제출 완료)'로 변경됩니다.)</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <span class=\"description-marker-anchor\">\n          <span class=\"description-target-marker\" aria-hidden=\"true\">2</span>\n          <button type=\"button\" class=\"btn-critical-primary modal-close\">견적 제출하기</button>\n        </span>\n        <button type=\"button\" class=\"btn-secondary modal-close\">취소</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerNegoRequest/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSearchTitle\">\n          <h3 id=\"descriptionSearchTitle\">검색/조회</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">수의계약 진행상태 정리 : 노란색 영역 참고\n\n협력업체에게는 아래의 상태만 안내함 </pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionQuoteReqTitle\">\n          <h3 id=\"descriptionQuoteReqTitle\">상세정보 · 견적 제출 및 확인(견적 요청 현황)</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">수의계약을 위한 견적이 다수 회 진행된 경우 차수별로 확인할 수 있음\n</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">‘수의계약을 위한 견적 요청 정보’ 화면으로 이동\n\n뒷페이지\n</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">제출여부에 따라 ‘견적 제출하기’, ‘견적 제출내역’ 버튼 제공</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionQuoteSubmitTitle\">\n          <h3 id=\"descriptionQuoteSubmitTitle\">견적 제출하기</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">수의계약이 ‘예정가’가 설정된 상태에서 진행된 경우,\n\n협력업체가 적정선(합리적인 가격)에서 수의계약을 위한 견적을 제출할 수 있도록, 예정가 제공\n</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionQuoteSubmitConfirmTitle\">\n          <h3 id=\"descriptionQuoteSubmitConfirmTitle\">견적 제출 시 유의사항</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">‘견적 제출하기’ 버튼 클릭 시 진행상태를 ‘수의계약(견적제출 완료)’ 로 변경</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerNotice/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSearchTitle\">\n          <h3 id=\"descriptionSearchTitle\">검색/조회</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">제목, 내용, 제목+내용 </pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerPreQuote/pqCancelSubmitConfirmModal.html": "<div class=\"modal-backdrop\" id=\"pqCancelSubmitConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"pqCancelSubmitTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"pqCancelSubmitTitle\">견적 제출 취소(삭제) 시 유의사항</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">견적 마감일시 이전에는 '견적 제출 취소'를 처리하신 후에도 견적 제출이 가능합니다.</p>\n            <p>견적 제출 취소(삭제)하시겠습니까?</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <button type=\"button\" class=\"btn-delete modal-close\">견적 제출 취소(삭제)</button>\n        <button type=\"button\" class=\"btn-secondary modal-close\">취소</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerPreQuote/pqGiveUpConfirmModal.html": "<div class=\"modal-backdrop\" id=\"pqGiveUpConfirmModal\" role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"pqGiveUpTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"pqGiveUpTitle\">견적 포기 시 유의사항</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">견적 마감일시 이전에는 '견적 포기'를 처리하신 후에도 견적 제출이 가능합니다.</p>\n            <p>견적 포기하시겠습니까?</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <button type=\"button\" class=\"btn-delete modal-close\">견적 포기</button>\n        <button type=\"button\" class=\"btn-secondary modal-close\">취소</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerPreQuote/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSearchTitle\">\n          <h3 id=\"descriptionSearchTitle\">검색/조회</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">해당 협력업체에게 요청된 ‘사전 견적’ 내역 제공</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">검색 구분 : 견적요청번호, 견적요청명</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">진행상태 정의\n\n견적 요청중 : 견적 마감일시 이전\n견적 마감 : 견적 마감일시 이후\n</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">제출상태 정의\n\n미제출 : 제출 안함\n제출완료 : 제출 함\n견적포기 : 견적 포기</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionDetailTitle\">\n          <h3 id=\"descriptionDetailTitle\">상세정보 / 견적처리</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">사전 견적 요청 시 전달할 내용을 입력한 경우에만 노출</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSubmitTitle\">\n          <h3 id=\"descriptionSubmitTitle\">견적 제출</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">본 협력업체에 등록된 담당자 선택\n(아래는 자동 완성)</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">고객 통보 : MSG-011</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMPartnerQna/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\" data-ui-scope=\"popup\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionSearchTitle\">\n          <h3 id=\"descriptionSearchTitle\">검색/조회</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">본 협력업체가 작성한 질문과 답변만 검색/조회</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">제목, 내용, 제목+내용, 답변</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionWriteTitle\">\n          <h3 id=\"descriptionWriteTitle\">질문 등록</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">질문 등록 시 고객 통보 : MSG-008</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionDetailTitle\">\n          <h3 id=\"descriptionDetailTitle\">상세보기(질문+답변)</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">답변이 등록된 경우 수정/삭제 불가\n\nAlert\n‘답변이 등록되어 수정/삭제는 불가능합니다.’</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">답변이 있는 경우에만 보여줌 </pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>"
});
